import { describe, it, expect } from 'vitest';
import fs from 'fs';
import path from 'path';
import {
  ballsToOversDisplay,
  normalizeMatchFormat,
  parseOutcome,
} from '../../../scripts/import-cricsheet.js';
import { HistFormat, HistResultType, HistMarginType } from '../src/index.js';

const FIXTURES_DIR = path.resolve(__dirname, '../stats/__fixtures__');

describe('Cricsheet Importer Unit Tests (Step 3)', () => {
  it('correctly converts legal balls to standard overs notation (111 balls = 18.3)', () => {
    expect(ballsToOversDisplay(0)).toBe('0.0');
    expect(ballsToOversDisplay(5)).toBe('0.5');
    expect(ballsToOversDisplay(6)).toBe('1.0');
    expect(ballsToOversDisplay(111)).toBe('18.3');
    expect(ballsToOversDisplay(120)).toBe('20.0');
    expect(ballsToOversDisplay(300)).toBe('50.0');
  });

  it('normalizes match formats correctly and separates international from franchise T20s', () => {
    expect(normalizeMatchFormat('T20', 'international')).toBe(HistFormat.T20I);
    expect(normalizeMatchFormat('T20', 'club')).toBe(HistFormat.T20);
    expect(normalizeMatchFormat('ODI', 'international')).toBe(HistFormat.ODI);
    expect(normalizeMatchFormat('Test', 'international')).toBe(HistFormat.TEST);
  });

  it('parses normal match result fixture (sample_t20i.json)', () => {
    const data = JSON.parse(
      fs.readFileSync(path.join(FIXTURES_DIR, 'sample_t20i.json'), 'utf8')
    );
    const outcome = parseOutcome(data.info.outcome);
    expect(outcome.resultType).toBe(HistResultType.WIN);
    expect(outcome.winnerTeamName).toBe('Sri Lanka');
    expect(outcome.marginType).toBe(HistMarginType.WICKETS);
    expect(outcome.marginValue).toBe(5);
    expect(outcome.method).toBeNull();
  });

  it('parses tie with super over eliminator fixture (sample_super_over.json)', () => {
    const data = JSON.parse(
      fs.readFileSync(path.join(FIXTURES_DIR, 'sample_super_over.json'), 'utf8')
    );
    const outcome = parseOutcome(data.info.outcome);
    expect(outcome.resultType).toBe(HistResultType.TIE);
    expect(outcome.winnerTeamName).toBe('Mumbai Indians');
    expect(outcome.marginType).toBeNull();
    // Verify super over innings exist
    const superOverInnings = data.innings.filter((inn: any) => inn.super_over === true);
    expect(superOverInnings.length).toBe(2);
  });

  it('parses D/L rain-affected match fixture (sample_dls_or_superover.json)', () => {
    const data = JSON.parse(
      fs.readFileSync(path.join(FIXTURES_DIR, 'sample_dls_or_superover.json'), 'utf8')
    );
    const outcome = parseOutcome(data.info.outcome);
    expect(outcome.resultType).toBe(HistResultType.WIN);
    expect(outcome.winnerTeamName).toBe('New Zealand');
    expect(outcome.method).toBe('D/L');
    expect(outcome.marginType).toBe(HistMarginType.RUNS);
    expect(outcome.marginValue).toBe(8);
  });

  it('parses Test draw match fixture (sample_test_draw.json)', () => {
    const data = JSON.parse(
      fs.readFileSync(path.join(FIXTURES_DIR, 'sample_test_draw.json'), 'utf8')
    );
    const outcome = parseOutcome(data.info.outcome);
    expect(outcome.resultType).toBe(HistResultType.DRAW);
    expect(outcome.winnerTeamName).toBeNull();
  });

  it('parses No Result match fixture (sample_no_result.json)', () => {
    const data = JSON.parse(
      fs.readFileSync(path.join(FIXTURES_DIR, 'sample_no_result.json'), 'utf8')
    );
    const outcome = parseOutcome(data.info.outcome);
    expect(outcome.resultType).toBe(HistResultType.NO_RESULT);
    expect(outcome.winnerTeamName).toBeNull();
  });

  it('imports sample_t20i.json into PostgreSQL and verifies idempotency', async () => {
    const { importMatchData } = await import('../../../scripts/import-cricsheet.js');
    const { prisma } = await import('../src/index.js');

    const data = JSON.parse(
      fs.readFileSync(path.join(FIXTURES_DIR, 'sample_t20i.json'), 'utf8')
    );
    const matchId = '1001349';

    // First import
    const firstResult = await importMatchData(matchId, data);
    // Second import should be skipped (idempotent)
    const secondResult = await importMatchData(matchId, data);
    expect(secondResult).toBe(false);

    // Verify stored match in DB
    const stored = await prisma.histMatch.findUnique({
      where: { cricsheetMatchId: matchId },
      include: {
        teamA: true,
        teamB: true,
        venue: true,
        innings: true,
      },
    });

    expect(stored).toBeDefined();
    expect(stored?.format).toBe(HistFormat.T20I);
    expect(stored?.innings.length).toBe(2);
    // Innings 1: Australia (168 runs)
    expect(stored?.innings[0].runs).toBe(168);
    // Innings 2: Sri Lanka (172 runs)
    expect(stored?.innings[1].runs).toBe(172);

    // Import super over fixture
    const soData = JSON.parse(
      fs.readFileSync(path.join(FIXTURES_DIR, 'sample_super_over.json'), 'utf8')
    );
    await importMatchData('1082625', soData);
    const storedSO = await prisma.histMatch.findUnique({
      where: { cricsheetMatchId: '1082625' },
      include: { innings: true, winner: true },
    });
    expect(storedSO).toBeDefined();
    expect(storedSO?.resultType).toBe(HistResultType.TIE);
    expect(storedSO?.winner?.name).toBe('Mumbai Indians');
    const soInnings = storedSO?.innings.filter((inn) => inn.isSuperOver);
    expect(soInnings?.length).toBe(2);

    // Import DLS fixture
    const dlsData = JSON.parse(
      fs.readFileSync(path.join(FIXTURES_DIR, 'sample_dls_or_superover.json'), 'utf8')
    );
    await importMatchData('1043991', dlsData);
    const storedDLS = await prisma.histMatch.findUnique({
      where: { cricsheetMatchId: '1043991' },
      include: { winner: true },
    });
    expect(storedDLS).toBeDefined();
    expect(storedDLS?.method).toBe('D/L');
    expect(storedDLS?.winner?.name).toBe('New Zealand');
  });
});
